690	int XPlayerSetPlaybackSettings(XPlayer* p,const XAudioPlaybackRate *rate)
691	{
692	    PlayerContext* mPriData = (PlayerContext*)p;
693	    //* send a set set playback message.
694	    AwMessage msg;
695	    memset(&msg, 0, sizeof(AwMessage));
696	    msg.messageId = XPLAYER_COMMAND_SET_PLAYRATE;
697	    msg.params[0] = (uintptr_t)&mPriData->mSemSetPlayBackSettings;
698	    msg.params[1] = (uintptr_t)&mPriData->mSetPlayBackSettingsReply;
699	    msg.params[2] = (uintptr_t)rate;
700	    AwMessageQueuePostMessage(mPriData->mMessageQueue, &msg);
701	    CdxSemTimedWait(&mPriData->mSemSetPlayBackSettings, -1);
702	
703	    if (rate->mSpeed == 0.f && mPriData->mStatus == XPLAYER_STATUS_STARTED)
704	    {
705	       logd("PlayerPause");
706	       XPlayerPause(p);
707	    }
708	    else if (rate->mSpeed != 0.f && (mPriData->mStatus == XPLAYER_STATUS_PAUSED
709	           || mPriData->mStatus == XPLAYER_STATUS_PREPARED
710	           || mPriData->mStatus == XPLAYER_STATUS_COMPLETE))
711	    {
712	       XPlayerStart(p);
713	    }
714	
715	    return mPriData->mSetPlayBackSettingsReply;
716	}
